def clean_price(text):
    for junk in ["₹", "Rs.", "Rs", "/-", ","]:
        text = text.replace(junk, "")
    return int(float(text.strip()))

def clean_code(text):
    text = text.upper().replace("-", "").replace(" ", "")
    letters = text.rstrip("0123456789")
    return (letters + " " + text[len(letters):]).strip()
